     1	import { Notification } from "../domain/notification";
     2	import { isEventKind } from "../domain/order";
     3	
     4	const VERSION = 2;
     5	const MAX_PAYLOAD = 900;
     6	
     7	interface WirePayload {
     8	  v: number;
     9	  o: string;
    10	  c: string;
    11	  k: string;
    12	}
    13	
    14	/** 탭·개행·제어문자는 와이어 형식(<key>TAB<payload>)을 깨므로 제거한다. */
    15	function scrub(s: string): string {
    16	  return s.replace(/[\u0000-\u001f\u007f]/g, "");
    17	}
    18	
    19	export function encodePayload(n: Notification): string {
    20	  const body: WirePayload = { v: VERSION, o: scrub(n.orderNo), c: scrub(n.customerId), k: n.kind };
    21	  const json = JSON.stringify(body);
    22	  if (json.length > MAX_PAYLOAD) throw new Error("payload too large");
    23	  return json;
    24	}
    25	
    26	export function decodePayload(raw: string): Notification | null {
    27	  let body: Partial<WirePayload>;
    28	  try {
    29	    body = JSON.parse(raw) as Partial<WirePayload>;
    30	  } catch {
    31	    return null;
    32	  }
    33	  if (body.v !== VERSION && body.v !== 1) return null;
    34	  if (typeof body.o !== "string" || typeof body.c !== "string" || !isEventKind(body.k)) return null;
    35	  return { orderNo: body.o, customerId: body.c, kind: body.k };
    36	}
