    10	export class OrderRepository {
    11	  private readonly orders = new Map<string, Order>();
    12	  /** 채널·제휴사·주문일별 일련번호 */
    13	  private readonly counters = new Map<string, number>();
    14	  private eventSeq = 0;
    15	
    16	  create(customerId: string, channel: Channel, placedOn: string, partner?: string): Order {
    17	    const counterKey = `${channel}|${partner ?? ""}|${placedOn}`;
    18	    const next = (this.counters.get(counterKey) ?? 0) + 1;
    19	    this.counters.set(counterKey, next);
    20	    const order: Order = {
    21	      orderNo: formatOrderNo(channel, placedOn, next, partner),
    22	      customerId,
    23	      channel,
    24	      partner,
    25	      placedOn,
    26	      events: [],
    27	    };
    28	    this.orders.set(order.orderNo, order);
    29	    return order;
    30	  }
    31	
    32	  find(orderNo: string): Order | undefined {
    33	    return this.orders.get(orderNo);
    34	  }
    35	
    36	  addEvent(orderNo: string, kind: OrderEventKind): number {
    37	    const order = this.orders.get(orderNo);
    38	    if (!order) throw new Error("order not found");
    39	    const seq = ++this.eventSeq;
    40	    order.events.push({ kind, seq, dispatched: false });
    41	    return seq;
    42	  }
