    44	  /** 아직 발송 회차에 실리지 않은 이벤트를 기록 순으로 꺼내고 실린 것으로 표시한다. */
    45	  takePending(): PendingEvent[] {
    46	    const out: PendingEvent[] = [];
    47	    for (const o of this.orders.values()) {
    48	      for (const e of o.events) {
    49	        if (e.dispatched) continue;
    50	        e.dispatched = true;
    51	        out.push({ orderNo: o.orderNo, customerId: o.customerId, kind: e.kind, seq: e.seq });
    52	      }
    53	    }
    54	    return out.sort((a, b) => a.seq - b.seq);
