=== src/util/format.ts
     1	/**
     2	 * 국내 휴대전화 번호를 숫자 11자리(010xxxxxxxx)로 정규화한다.
     3	 * +82 국가번호·하이픈·공백·괄호를 허용한다. 정규화할 수 없으면 null.
     4	 */
     5	export function normalizeMobile(raw: string): string | null {
     6	  let digits = raw.replace(/[\s\-()]/g, "");
     7	  if (digits.startsWith("+82")) digits = "0" + digits.slice(3);
     8	  else if (digits.startsWith("82") && digits.length === 12) digits = "0" + digits.slice(2);
     9	  if (!/^\d+$/.test(digits)) return null;
    10	  if (!/^01[016789]\d{7,8}$/.test(digits)) return null;
    11	  if (digits.length === 10) digits = digits.slice(0, 3) + "0" + digits.slice(3);
    12	  return digits;
    13	}
    14	
    15	export function maskMobile(n: string): string {
    16	  return n.length === 11 ? `${n.slice(0, 3)}-****-${n.slice(7)}` : "***";
    17	}
    18	
    19	/** 표시 폭(한글 2칸, 그 외 1칸) */
    20	export function displayWidth(s: string): number {
    21	  let w = 0;
    22	  for (const ch of s) w += /[ᄀ-ᇿ㄰-㆏가-힣]/.test(ch) ? 2 : 1;
