 * 해시를 앞에 두는 이유: mqpub 3.4.1은 한 배치 안에서 키의 앞 16바이트가 같은
 * 메시지를 소리 없이 하나로 합친다(발행 건수는 그대로 보고). 주문번호만으로 키를
 * 만들면 같은 날 주문끼리 앞부분이 겹쳐 문자가 누락되므로, 앞 16자를 주문·이벤트별로 다르게 한다.
 */
export function messageKey(namespace: string, kind: OrderEventKind, orderNo: string): string {
  const digest = createHash("sha256").update(`${orderNo}|${kind}`).digest("hex").slice(0, 16);
  return `${digest}.${namespace}.${KIND_CODE[kind]}.${orderNo}`;
}

